   except Exception as exc:print('PRECHECK_ERROR',ci,name,repr(exc),flush=True)
  for ar in range(3):
   for name,cfg in allowed[ar:]+allowed[:ar]:
    if cfg is not None:configs.CONFIGS[key]=cfg
